pipe-and-filter.pseudocode:
def source(path):  # 데이터 소스
    for line in read_lines(path):
        yield line

def select(lines, word):  # 필터1: 선택
    for line in lines:
        if word in line:
            yield line

def to_upper(lines):  # 필터2: 변환
    for line in lines:
        yield line.upper()

def run(path):
    # 파이프 = 제너레이터 연결, 필터 재조합 가능
    pipe = to_upper(select(source(path), 'ERROR'))
    for out in pipe:  # 데이터 싱크
        write(out)
